// 639 Hz — fréquence de cohérence et d'harmonie
// CanResonate: true when coherence > 0.7
export function canResonate(coherence: number): boolean {
  return coherence > 0.7;
}

export function pulseAt639(timestamp: number): number {
  return Math.sin((2 * Math.PI * 639 * timestamp) / 1000);
}

content.rust:
pub const RESONANCE_FREQ: f64 = 639.0;
pub const COHERENCE_THRESHOLD: f64 = 0.7;

/// CanResonate — capacité déclarée, pas inférée
pub fn can_resonate(coherence: f64) -> bool {
    coherence > COHERENCE_THRESHOLD
}

/// Retourne la valeur du sinus à 639 Hz au timestamp donné (ms)
pub fn pulse_at_639(timestamp_ms: f64) -> f64 {
    (2.0 * std::f64::consts::PI * RESONANCE_FREQ * timestamp_ms / 1000.0).sin()
}
